const dbClient=createClient({url:databaseUrl,authToken:databaseToken});
const txStore=new AsyncLocalStorage();
function bindArgs(args){return args.length===1&&Array.isArray(args[0])?args[0]:args;}
function runner(){return txStore.getStore()||dbClient;}
const db={
  prepare(sql){return {
    async get(...args){const r=await runner().execute({sql,args:bindArgs(args)});return r.rows[0];},
    async all(...args){const r=await runner().execute({sql,args:bindArgs(args)});return r.rows;},
    async run(...args){const r=await runner().execute({sql,args:bindArgs(args)});return {changes:Number(r.rowsAffected||0),lastInsertRowid:r.lastInsertRowid===undefined?undefined:Number(r.lastInsertRowid)};}
  };},
  async exec(sql){return runner().executeMultiple(sql);},
  async transaction(fn){
    const tx=await dbClient.transaction('write');
    try{const result=await txStore.run(tx,()=>fn());await tx.commit();return result;}
    catch(e){try{await tx.rollback();}catch(_){}throw e;}
    finally{try{tx.close();}catch(_){} }
  }
};
const SCHEMA_SQL=`
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT DEFAULT '',starting_price REAL,badge TEXT DEFAULT '',featured INTEGER DEFAULT 0,visible INTEGER DEFAULT 1,display_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS service_photos(id INTEGER PRIMARY KEY AUTOINCREMENT,service_id INTEGER NOT NULL,image_url TEXT NOT NULL,display_order INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_materials(id INTEGER PRIMARY KEY AUTOINCREMENT,service_id INTEGER NOT NULL,item_id INTEGER NOT NULL,quantity_per_order REAL NOT NULL DEFAULT 0,UNIQUE(service_id,item_id));
CREATE TABLE IF NOT EXISTS gallery(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,image_url TEXT NOT NULL,featured INTEGER DEFAULT 0,visible INTEGER DEFAULT 1,display_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS enquiries(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_name TEXT NOT NULL,phone TEXT NOT NULL,service TEXT NOT NULL,size TEXT DEFAULT '',quantity INTEGER DEFAULT 1,requirement TEXT DEFAULT '',delivery INTEGER DEFAULT 0,installation INTEGER DEFAULT 0,status TEXT DEFAULT 'NEW',quotation_amount REAL,admin_notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_name TEXT NOT NULL,rating INTEGER NOT NULL,review TEXT NOT NULL,approved INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enquiry_history(id INTEGER PRIMARY KEY AUTOINCREMENT,enquiry_id INTEGER NOT NULL,event_type TEXT NOT NULL,event_label TEXT NOT NULL,note TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,type TEXT DEFAULT 'INFO',is_read INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,enquiry_id INTEGER NOT NULL UNIQUE,customer_id INTEGER,order_number TEXT UNIQUE NOT NULL,service TEXT NOT NULL,quantity INTEGER DEFAULT 1,size TEXT DEFAULT '',requirement TEXT DEFAULT '',delivery INTEGER DEFAULT 0,installation INTEGER DEFAULT 0,amount REAL NOT NULL,status TEXT DEFAULT 'CONFIRMED',payment_status TEXT DEFAULT 'UNPAID',payment_method TEXT DEFAULT '',customer_note TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity TEXT DEFAULT '',entity_id TEXT DEFAULT '',details TEXT DEFAULT '',ip_address TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL,success INTEGER DEFAULT 0,ip_address TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER NOT NULL,subject TEXT NOT NULL,category TEXT DEFAULT 'GENERAL',priority TEXT DEFAULT 'NORMAL',status TEXT DEFAULT 'OPEN',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ticket_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,ticket_id INTEGER NOT NULL,user_id INTEGER,role TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT DEFAULT 'GENERAL',unit TEXT DEFAULT 'pcs',stock REAL NOT NULL DEFAULT 0,min_stock REAL NOT NULL DEFAULT 0,cost_per_unit REAL NOT NULL DEFAULT 0,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER NOT NULL,type TEXT NOT NULL,quantity REAL NOT NULL,note TEXT DEFAULT '',order_id INTEGER,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL UNIQUE,stage TEXT NOT NULL DEFAULT 'PENDING',assigned_to INTEGER,expected_date TEXT,notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deliveries(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL UNIQUE,type TEXT NOT NULL DEFAULT 'DELIVERY',scheduled_date TEXT,scheduled_time TEXT,address TEXT DEFAULT '',contact_phone TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'SCHEDULED',notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS staff_assignments(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,user_id INTEGER NOT NULL,task TEXT NOT NULL DEFAULT 'GENERAL',created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(order_id,user_id,task));
CREATE TABLE IF NOT EXISTS business_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '',updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_reset_tokens(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,used INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT DEFAULT '',email TEXT DEFAULT '',address TEXT DEFAULT '',active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_purchases(id INTEGER PRIMARY KEY AUTOINCREMENT,supplier_id INTEGER,item_id INTEGER,quantity REAL NOT NULL,cost_per_unit REAL NOT NULL,total_cost REAL NOT NULL,purchase_date TEXT NOT NULL,note TEXT DEFAULT '',created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS staff_profiles(user_id INTEGER PRIMARY KEY,phone TEXT DEFAULT '',designation TEXT DEFAULT '',joined_date TEXT,notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS staff_attendance(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,attendance_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PRESENT',note TEXT DEFAULT '',created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,attendance_date));
`;
let dbReady=null;
async function initDb(){
 if(!dbReady){dbReady=(async()=>{
  await db.exec(SCHEMA_SQL);
  const alters=['ALTER TABLE enquiries ADD COLUMN customer_id INTEGER',"ALTER TABLE orders ADD COLUMN payment_status TEXT DEFAULT 'UNPAID'","ALTER TABLE orders ADD COLUMN payment_method TEXT DEFAULT ''",'ALTER TABLE orders ADD COLUMN payment_amount REAL DEFAULT 0',"ALTER TABLE enquiries ADD COLUMN quotation_status TEXT DEFAULT 'PENDING'","ALTER TABLE enquiries ADD COLUMN quotation_customer_note TEXT DEFAULT ''",'ALTER TABLE enquiries ADD COLUMN quotation_responded_at TEXT',"ALTER TABLE orders ADD COLUMN refund_status TEXT DEFAULT 'NOT_REQUESTED'",'ALTER TABLE orders ADD COLUMN refund_amount REAL DEFAULT 0',"ALTER TABLE orders ADD COLUMN refund_note TEXT DEFAULT ''"];
  for(const sql of alters){try{await db.exec(sql)}catch(e){}}
  const c=await db.prepare('SELECT COUNT(*) c FROM services').get();
  if(Number(c?.c||0)===0){const ins=db.prepare('INSERT INTO services(name,description,display_order) VALUES(?,?,?)');for(const x of [['LED Boards','Illuminated boards for shops and businesses.',1],['Name Plates','Custom home and office name plates.',2],['Number Plates','Customized number plates.',3],['Laser Cutting','Custom laser cutting work.',4],['Acrylic & 3D Letters','Premium acrylic and 3D letters.',5],['Radium Work','Customized radium work.',6]]) await ins.run(...x);}
  await db.exec(`CREATE TABLE IF NOT EXISTS business_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '')`);
  for(const sql of [
   `CREATE TABLE IF NOT EXISTS inventory_items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT DEFAULT 'GENERAL',unit TEXT DEFAULT 'pcs',stock REAL DEFAULT 0,min_stock REAL DEFAULT 0,cost_per_unit REAL DEFAULT 0,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP)`,
   `CREATE TABLE IF NOT EXISTS inventory_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER NOT NULL,type TEXT NOT NULL,quantity REAL NOT NULL,note TEXT DEFAULT '',order_id INTEGER,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP)`,
   `CREATE TABLE IF NOT EXISTS production_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL UNIQUE,stage TEXT DEFAULT 'PENDING',assigned_to INTEGER,expected_date TEXT,notes TEXT DEFAULT '',updated_at TEXT DEFAULT CURRENT_TIMESTAMP,created_at TEXT DEFAULT CURRENT_TIMESTAMP)`,
   `CREATE TABLE IF NOT EXISTS deliveries(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL UNIQUE,type TEXT DEFAULT 'DELIVERY',scheduled_date TEXT,scheduled_time TEXT,address TEXT DEFAULT '',contact_phone TEXT DEFAULT '',status TEXT DEFAULT 'SCHEDULED',notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP)`,
   `CREATE TABLE IF NOT EXISTS staff_assignments(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,user_id INTEGER NOT NULL,task TEXT DEFAULT 'GENERAL',created_at TEXT DEFAULT CURRENT_TIMESTAMP)`
  ]) await db.exec(sql);
  for(const q of [
   `ALTER TABLE orders ADD COLUMN payment_amount REAL DEFAULT 0`,
   `ALTER TABLE enquiries ADD COLUMN customer_id INTEGER`,
   `ALTER TABLE enquiries ADD COLUMN quotation_status TEXT DEFAULT 'PENDING'`,
   `ALTER TABLE enquiries ADD COLUMN quotation_customer_note TEXT DEFAULT ''`,
   `ALTER TABLE enquiries ADD COLUMN quotation_responded_at TEXT`
  ]) { try { await db.exec(q); } catch(e) {} }
  await db.prepare("UPDATE enquiries SET quotation_status='SENT' WHERE quotation_amount IS NOT NULL AND (quotation_status IS NULL OR quotation_status='PENDING') AND status='QUOTATION SENT'").run();
 })().catch(e=>{dbReady=null;throw e});}
 return dbReady;
}
app.use(express.json({limit:'10mb'}));app.use(express.urlencoded({extended:true}));
app.use(async (req,res,next)=>{try{await initDb();next()}catch(e){next(e)}});
const uploadDir=path.join(__dirname,'uploads','gallery');
if(!isVercel)fs.mkdirSync(uploadDir,{recursive:true});
const storage=multer.memoryStorage();
const upload=multer({storage,limits:{files:12,fileSize:4*1024*1024},fileFilter:(req,file,cb)=>cb(null,/^image\/(jpeg|png|webp|gif)$/.test(file.mimetype))});
function imageSignatureOk(file){try{const b=file?.buffer;if(!b)return false;if(file.mimetype==='image/jpeg')return b.length>3&&b[0]===255&&b[1]===216&&b[2]===255;if(file.mimetype==='image/png')return b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));if(file.mimetype==='image/gif')return ['GIF87a','GIF89a'].includes(b.subarray(0,6).toString());if(file.mimetype==='image/webp')return b.subarray(0,4).toString()==='RIFF'&&b.subarray(8,12).toString()==='WEBP';return false}catch(e){return false}}
function validateUploadedFiles(files){if((files||[]).some(f=>!imageSignatureOk(f)))throw new Error('One or more uploaded files are not valid image files.')}
async function storeImage(file){
 if(isVercel || process.env.BLOB_READ_WRITE_TOKEN){const ext=path.extname(file.originalname||'').toLowerCase()||'.jpg';const safe=path.basename(file.originalname||'photo',ext).replace(/[^a-z0-9-_]/gi,'-').slice(0,50)||'photo';const blob=await put(`rudra-arts/gallery/${Date.now()}-${Math.random().toString(36).slice(2,8)}-${safe}${ext}`,file.buffer,{access:'public',addRandomSuffix:true,contentType:file.mimetype});return blob.url;}
 const ext=path.extname(file.originalname||'').toLowerCase()||'.jpg';const safe=path.basename(file.originalname||'photo',ext).replace(/[^a-z0-9-_]/gi,'-').slice(0,50)||'photo';const filename=Date.now()+'-'+Math.random().toString(36).slice(2,8)+'-'+safe+ext;fs.writeFileSync(path.join(uploadDir,filename),file.buffer);return '/uploads/gallery/'+filename;
}
async function deleteStoredImage(url){if(!url)return;if(url.startsWith('http')){try{await del(url)}catch(e){}}else if(url.startsWith('/uploads/')){try{fs.unlinkSync(path.join(__dirname,url))}catch(e){}}}
