function parseCookies(req){const out={};for(const part of String(req.headers.cookie||'').split(';')){const i=part.indexOf('=');if(i>0)out[part.slice(0,i).trim()]=decodeURIComponent(part.slice(i+1).trim())}return out}
function auth(req,res,next){try{const cookies=parseCookies(req),bearer=(req.headers.authorization||'').replace(/^Bearer\s+/i,''),raw=bearer||cookies.ra_token;if(!raw)throw new Error('missing token');req.user=jwt.verify(raw,SECRET);if(['POST','PUT','PATCH','DELETE'].includes(req.method)&&req.headers.origin){const expected=`${req.protocol}://${req.get('host')}`;if(req.headers.origin!==expected)return res.status(403).json({error:'Cross-site request blocked.'})}next()}catch(e){res.status(401).json({error:'Unauthorized'})}}
const allow=(...roles)=>(req,res,next)=>roles.includes(req.user.role)?next():res.status(403).json({error:'Forbidden'});
function ip(req){return String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'').split(',')[0].trim().slice(0,100)}
async function logActivity(userId,action,entity='',entityId='',details='',address=''){await db.prepare('INSERT INTO activity_logs(user_id,action,entity,entity_id,details,ip_address) VALUES(?,?,?,?,?,?)').run(userId||null,action,entity,String(entityId||''),String(details||'').slice(0,1000),address||'')}
async function notify(userId,title,message,type='INFO'){if(!userId)return;await db.prepare('INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)').run(userId,title,message,type)}
async function removeUploadedFileIfUnused(imageUrl){if(!imageUrl)return;const used=await db.prepare('SELECT 1 FROM gallery WHERE image_url=? UNION SELECT 1 FROM service_photos WHERE image_url=? LIMIT 1').get(imageUrl,imageUrl);if(!used)await deleteStoredImage(imageUrl)}
function normalizeMoney(v,label,max=100000000){const n=Number(v);if(!Number.isFinite(n)||n<0||n>max)throw new Error(`${label} must be a valid non-negative amount.`);return Math.round(n*100)/100}
function serviceFlag(v,defaultValue=0){if(v===undefined)return defaultValue;return v===true||v===1||v==='1'||String(v).toLowerCase()==='true'?1:0}
function cleanText(v,max=500){return String(v??'').trim().slice(0,max)}
function validEmail(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v||'').trim())}
function validPhone(v){return /^(?:\+?91[-\s]?)?[6-9]\d{9}$/.test(String(v||'').replace(/[()]/g,'').trim())}
function validDate(v){if(!v)return true;const s=String(v);if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const [y,m,d]=s.split('-').map(Number);const dt=new Date(Date.UTC(y,m-1,d));return dt.getUTCFullYear()===y&&dt.getUTCMonth()===m-1&&dt.getUTCDate()===d}
function validTime(v){return !v || /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(String(v))}
function escapeHtml(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;')}
function validateEnquiryPayload(x,customerMode=false){const name=cleanText(x.customer_name,100),phone=cleanText(x.phone,40),service=cleanText(x.service,100),size=cleanText(x.size,200),requirement=cleanText(x.requirement,2000),qty=Number(x.quantity??1);if(!service)return {error:'Service is required'};if(!customerMode&&(!name||!phone))return {error:'Name and phone are required'};if(phone&&!validPhone(phone))return {error:'Enter a valid Indian phone number'};if(!Number.isInteger(qty)||qty<1||qty>10000)return {error:'Quantity must be a whole number between 1 and 10000'};return {name,phone,service,size,quantity:qty,requirement}}
const ORDER_STATUSES=['CONFIRMED','IN PROGRESS','READY','COMPLETED','CANCELLED'];const ORDER_TRANSITIONS={'CONFIRMED':new Set(['CONFIRMED','IN PROGRESS','CANCELLED']),'IN PROGRESS':new Set(['IN PROGRESS','CONFIRMED','READY','CANCELLED']),'READY':new Set(['READY','IN PROGRESS','COMPLETED','CANCELLED']),'COMPLETED':new Set(['COMPLETED']),'CANCELLED':new Set(['CANCELLED','CONFIRMED'])};const PRODUCTION_STAGE_STATUS={PENDING:'CONFIRMED',DESIGN:'IN PROGRESS',CUTTING:'IN PROGRESS',ASSEMBLY:'IN PROGRESS','QUALITY CHECK':'IN PROGRESS',READY:'READY'};const STATUS_STAGE={CONFIRMED:'PENDING','IN PROGRESS':'DESIGN',READY:'READY'};function assertOrderTransition(before,next){if(!ORDER_STATUSES.includes(next))throw new Error('Invalid order status');if(before===next)return;if(before==='COMPLETED')throw new Error('Completed orders cannot move backwards.');if(!ORDER_TRANSITIONS[before]?.has(next))throw new Error(`Invalid order transition: ${before} → ${next}`)}async function syncProductionStageForOrder(order,status){const stage=STATUS_STAGE[status];if(stage)await db.prepare('UPDATE production_jobs SET stage=?,updated_at=CURRENT_TIMESTAMP WHERE order_id=?').run(stage,order.id)}
async function consumeInventoryForOrder(order,userId){const materials=await db.prepare(`SELECT sm.item_id,sm.quantity_per_order,i.name,i.unit,i.stock FROM service_materials sm JOIN services s ON s.id=sm.service_id JOIN inventory_items i ON i.id=sm.item_id WHERE s.name=? AND i.active=1`).all(order.service);for(const m of materials){const need=Number(m.quantity_per_order)*Number(order.quantity||1);if(!Number.isFinite(need)||need<=0)continue;if(Number(m.stock)<need)throw new Error(`Insufficient stock for ${m.name}. Required ${need} ${m.unit}, available ${m.stock} ${m.unit}.`)}for(const m of materials){const need=Number(m.quantity_per_order)*Number(order.quantity||1);if(need<=0)continue;await db.prepare('UPDATE inventory_items SET stock=stock-?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(need,m.item_id);await db.prepare('INSERT INTO inventory_movements(item_id,type,quantity,note,order_id,created_by) VALUES(?,?,?,?,?,?)').run(m.item_id,'OUT',need,`Automatic consumption for ${order.order_number}`,order.id,userId)}return materials.length}
async function reverseInventoryForCancelledOrder(order,userId){const moves=await db.prepare("SELECT * FROM inventory_movements WHERE order_id=? AND type='OUT' AND note LIKE 'Automatic consumption for %'").all(order.id);let count=0;for(const m of moves){const already=await db.prepare("SELECT 1 FROM inventory_movements WHERE order_id=? AND item_id=? AND type='IN' AND note LIKE 'Reversal for cancelled %' AND id>? LIMIT 1").get(order.id,m.item_id,m.id);if(already)continue;await db.prepare('UPDATE inventory_items SET stock=stock+?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(m.quantity,m.item_id);await db.prepare('INSERT INTO inventory_movements(item_id,type,quantity,note,order_id,created_by) VALUES(?,?,?,?,?,?)').run(m.item_id,'IN',m.quantity,`Reversal for cancelled ${order.order_number}`,order.id,userId);count++}return count}
app.use('/api/admin',(req,res,next)=>{if(['POST','PATCH','PUT','DELETE'].includes(req.method)&&req.path!=='/auth/login'){const finish=()=>{if(req.user){const safeBody={...req.body};for(const k of ['password','password_hash','token'])delete safeBody[k];logActivity(req.user.id,req.method+' '+req.path,req.path.split('/')[3]||'admin',req.params?.id||'',JSON.stringify(safeBody),ip(req))}};res.on('finish',finish)}next()});
app.post('/api/auth/login',async (req,res)=>{const email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||''),address=ip(req);const recent=(await db.prepare("SELECT COUNT(*) c FROM login_attempts WHERE email=? AND ip_address=? AND success=0 AND created_at >= datetime('now','-15 minutes')").get(email,address)).c;const ipRecent=(await db.prepare("SELECT COUNT(*) c FROM login_attempts WHERE ip_address=? AND success=0 AND created_at >= datetime('now','-15 minutes')").get(address)).c;if(recent>=5||ipRecent>=20){await db.prepare('INSERT INTO login_attempts(email,success,ip_address) VALUES(?,?,?)').run(email,0,address);return res.status(429).json({error:'Too many failed login attempts. Try again after 15 minutes.'})}const u=await db.prepare('SELECT * FROM users WHERE email=?').get(email),ok=!!(u&&u.active&&bcrypt.compareSync(password,u.password_hash));await db.prepare('INSERT INTO login_attempts(email,success,ip_address) VALUES(?,?,?)').run(email,ok?1:0,address);if(!ok)return res.status(401).json({error:'Invalid credentials'});const token=jwt.sign({id:u.id,name:u.name,email:u.email,role:u.role},SECRET,{expiresIn:'8h'});res.setHeader('Set-Cookie',`ra_token=${encodeURIComponent(token)}; Max-Age=28800; Path=/; HttpOnly; SameSite=Lax${process.env.NODE_ENV==='production'?'; Secure':''}`);if(u.role!=='CUSTOMER')logActivity(u.id,'LOGIN','AUTH',u.id,'Login successful',address);res.json({user:{id:u.id,name:u.name,email:u.email,role:u.role}})});
app.post('/api/auth/logout',async (req,res)=>{res.setHeader('Set-Cookie','ra_token=; Max-Age=0; Path=/; HttpOnly; SameSite=Lax');res.json({ok:true})});
