app.post('/api/customer/enquiries/:id/confirm-order',auth,allow('CUSTOMER'),async (req,res)=>{
 const q=await db.prepare('SELECT * FROM enquiries WHERE id=? AND customer_id=?').get(req.params.id,req.user.id);
 if(!q)return res.status(404).json({error:'Enquiry not found'});
 if(q.quotation_amount==null)return res.status(400).json({error:'Quotation is not available yet'});
 if(q.quotation_status!=='ACCEPTED')return res.status(400).json({error:'Please accept the quotation first'});
 const existing=await db.prepare('SELECT * FROM orders WHERE enquiry_id=?').get(q.id);
 if(existing)return res.json({ok:true,order:existing,alreadyExists:true});
 const tx=db.transaction(async ()=>{
   const orderNo='RAO'+String(q.id).padStart(5,'0');
   const order=await db.prepare(`INSERT INTO orders(enquiry_id,customer_id,order_number,service,quantity,size,requirement,delivery,installation,amount,status,customer_note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).run(q.id,req.user.id,orderNo,q.service,q.quantity,q.size,q.requirement,q.delivery,q.installation,q.quotation_amount,'CONFIRMED',String(req.body.note||''));
   const created=await db.prepare('SELECT * FROM orders WHERE id=?').get(order.lastInsertRowid);
   const inventoryConsumed=await consumeInventoryForOrder(created,req.user.id);
   await db.prepare("UPDATE enquiries SET status='CONFIRMED' WHERE id=?").run(q.id);
   await db.prepare('INSERT INTO enquiry_history(enquiry_id,event_type,event_label,note) VALUES(?,?,?,?)').run(q.id,'ORDER','Order confirmed',`Order ${orderNo} created from accepted quotation`);
   notify(req.user.id,'Order confirmed',`Your order ${orderNo} is confirmed. Status: CONFIRMED.`,'ORDER');
   return await db.prepare('SELECT * FROM orders WHERE id=?').get(order.lastInsertRowid);
 });
 try{const order=await tx();res.status(201).json({ok:true,order,inventoryConsumed:(await db.prepare("SELECT COUNT(*) c FROM inventory_movements WHERE order_id=? AND type='OUT' AND note LIKE 'Automatic consumption for %'").get(order.id)).c})}catch(e){res.status(400).json({error:e.message||'Could not confirm order'})}
});
