app.get('/api/admin/analytics',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{try{
  // Keep analytics compatible with both local SQLite/libSQL and Turso.
  // We intentionally aggregate in JavaScript instead of relying on PRAGMA/strftime
  // behavior that can differ between local and remote libSQL environments.
  const rows=await db.prepare('SELECT * FROM orders ORDER BY id DESC').all();
  let totalRevenue=0,paidRevenue=0,pendingPayment=0;
  const statusMap=new Map(),paymentMap=new Map(),monthMap=new Map();
  for(const o of rows){
    const amount=Number(o.amount||0);
    const cancelled=String(o.status||'').toUpperCase()==='CANCELLED';
    const paymentStatus=String(o.payment_status||'UNPAID').toUpperCase();
    const paymentAmount=Number(o.payment_amount||0);
    if(!cancelled){
      totalRevenue+=amount;
      const paid=paymentStatus==='PAID'?amount:(paymentStatus==='PARTIAL'?Math.min(Math.max(paymentAmount,0),amount):0);
      paidRevenue+=paid;
      pendingPayment+=Math.max(0,amount-paid);
    }
    const st=String(o.status||'UNKNOWN');
    statusMap.set(st,(statusMap.get(st)||0)+1);
    paymentMap.set(paymentStatus,(paymentMap.get(paymentStatus)||0)+1);
    if(!cancelled){
      const raw=String(o.created_at||'');
      const m=/^(\\d{4})-(\\d{2})/.exec(raw);
      if(m){const key=m[1]+'-'+m[2];const cur=monthMap.get(key)||{month:key,revenue:0,orders:0};cur.revenue+=amount;cur.orders+=1;monthMap.set(key,cur);}
    }
  }
  const statusRows=[...statusMap.entries()].map(([status,count])=>({status,count})).sort((a,b)=>b.count-a.count);
  const paymentRows=[...paymentMap.entries()].map(([payment_status,count])=>({payment_status,count})).sort((a,b)=>b.count-a.count);
  const monthly=[...monthMap.values()].sort((a,b)=>a.month.localeCompare(b.month)).slice(-12);
  res.json({totalOrders:rows.length,totalRevenue,paidRevenue,pendingPayment,statusRows,paymentRows,monthly});
}catch(e){console.error('GET /api/admin/analytics failed:',e);res.status(500).json({error:'Dashboard analytics failed',details:String(e.message||e)})}});
