app.patch('/api/admin/enquiries/:id',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const before=await db.prepare('SELECT * FROM enquiries WHERE id=?').get(req.params.id);if(!before)return res.status(404).json({error:'Enquiry not found'});
 if('quotation_amount' in req.body){try{req.body.quotation_amount=normalizeMoney(req.body.quotation_amount,'Quotation amount')}catch(e){return res.status(400).json({error:e.message})}}
 if('status' in req.body){const allowedStatus=['NEW','UNDER REVIEW','QUOTATION SENT','CONFIRMED','IN PROGRESS','READY','COMPLETED','CANCELLED'];req.body.status=String(req.body.status).toUpperCase();if(!allowedStatus.includes(req.body.status))return res.status(400).json({error:'Invalid enquiry status'});}
 const sendingQuote=String(req.body.status||'').toUpperCase()==='QUOTATION SENT'||'quotation_amount' in req.body||'quotation_customer_note' in req.body;
 if(sendingQuote&&before.quotation_amount==null&&!('quotation_amount' in req.body))return res.status(400).json({error:'Quotation amount is required before sending a quotation.'});
 const keys=['status','quotation_amount','admin_notes','quotation_customer_note'].filter(k=>k in req.body);if(sendingQuote&&!keys.includes('quotation_status'))keys.push('quotation_status');if(!keys.length)return res.status(400).json({error:'Nothing to update'});
 const vals=keys.map(k=>k==='quotation_status'?'SENT':req.body[k]);await db.prepare(`UPDATE enquiries SET ${keys.map(k=>k+'=?').join(',')}${sendingQuote?',quotation_responded_at=NULL':''} WHERE id=?`).run(...vals,req.params.id);
 const after=await db.prepare('SELECT e.*,u.name customer_name FROM enquiries e LEFT JOIN users u ON u.id=e.customer_id WHERE e.id=?').get(req.params.id);if('status' in req.body&&before.status!==after.status)await db.prepare('INSERT INTO enquiry_history(enquiry_id,event_type,event_label,note) VALUES(?,?,?,?)').run(after.id,'STATUS',after.status,'Status updated by admin');if(sendingQuote){await db.prepare('INSERT INTO enquiry_history(enquiry_id,event_type,event_label,note) VALUES(?,?,?,?)').run(after.id,'QUOTATION','Quotation sent',`₹${Number(after.quotation_amount).toLocaleString('en-IN')}`);if(after.customer_id)notify(after.customer_id,'New quotation received',`Your quotation for ${after.service} is ₹${Number(after.quotation_amount).toLocaleString('en-IN')}. Open your portal to accept or reject it.`,'QUOTATION');}
 let whatsappUrl=null;if(after&&after.quotation_amount!=null){const msg=encodeURIComponent(`Hello ${after.customer_name||'Customer'},%0AYour quotation from Rudra Arts #1771 is ready.%0AEnquiry: #RA${String(after.id).padStart(4,'0')}%0AService: ${after.service}%0AQuotation: ₹${after.quotation_amount}%0A${after.quotation_customer_note||''}%0APlease open your Customer Portal to accept or reject the quotation.`);whatsappUrl=`https://wa.me/${String(after.phone||'').replace(/\D/g,'')||'918080330153'}?text=${msg}`}res.json({ok:true,quotationStatus:after.quotation_status,whatsappUrl})});
app.post('/api/customer/enquiries/:id/quotation-response',auth,allow('CUSTOMER'),async (req,res)=>{const decision=req.body.decision==='ACCEPTED'?'ACCEPTED':req.body.decision==='REJECTED'?'REJECTED':null;if(!decision)return res.status(400).json({error:'Invalid quotation decision'});const q=await db.prepare('SELECT id,status,quotation_amount,quotation_status FROM enquiries WHERE id=? AND customer_id=?').get(req.params.id,req.user.id);if(!q)return res.status(404).json({error:'Enquiry not found'});if(q.quotation_amount==null||q.quotation_status!=='SENT')return res.status(400).json({error:'Quotation is not available for response.'});await db.prepare('UPDATE enquiries SET quotation_status=?,quotation_responded_at=?,status=? WHERE id=? AND customer_id=?').run(decision,new Date().toISOString(),decision==='ACCEPTED'?'CONFIRMED':'UNDER REVIEW',req.params.id,req.user.id);await db.prepare('INSERT INTO enquiry_history(enquiry_id,event_type,event_label,note) VALUES(?,?,?,?)').run(req.params.id,'QUOTATION_RESPONSE',`Customer ${decision.toLowerCase()} quotation`,'Customer responded from portal');await db.prepare('INSERT INTO enquiry_history(enquiry_id,event_type,event_label,note) VALUES(?,?,?,?)').run(req.params.id,'STATUS',decision==='ACCEPTED'?'CONFIRMED':'UNDER REVIEW','Status updated from customer response');(await db.prepare("SELECT id FROM users WHERE role IN ('ADMIN','SUPER_ADMIN') AND active=1").all()).forEach(a=>notify(a.id,'Quotation response',`Customer ${decision.toLowerCase()} quotation for enquiry #RA${String(req.params.id).padStart(4,'0')}.`,'QUOTATION_RESPONSE'));res.json({ok:true,status:decision});});
