app.patch('/api/admin/orders/:id',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const before=await db.prepare('SELECT * FROM orders WHERE id=?').get(req.params.id);if(!before)return res.status(404).json({error:'Order not found'});const statusAllowed=['CONFIRMED','IN PROGRESS','READY','COMPLETED','CANCELLED'];const paymentAllowed=['UNPAID','PARTIAL','PAID'];if('status' in req.body){req.body.status=String(req.body.status).toUpperCase();if(!statusAllowed.includes(req.body.status))return res.status(400).json({error:'Invalid order status'})};const amount=Number(before.amount);let paymentAmount='payment_amount' in req.body?Number(req.body.payment_amount):Number(before.payment_amount||0);if(!Number.isFinite(paymentAmount)||paymentAmount<0||paymentAmount>amount)return res.status(400).json({error:'Payment amount must be between ₹0 and the order total.'});paymentAmount=Math.round(paymentAmount*100)/100;let paymentStatus='payment_status' in req.body?String(req.body.payment_status).toUpperCase():null;if(paymentStatus&&!paymentAllowed.includes(paymentStatus))return res.status(400).json({error:'Invalid payment status'});if('payment_amount' in req.body&&!paymentStatus)paymentStatus=paymentAmount===0?'UNPAID':paymentAmount===amount?'PAID':'PARTIAL';if(!paymentStatus)paymentStatus=before.payment_status||'UNPAID';if(paymentStatus==='PAID')paymentAmount=amount;if(paymentStatus==='UNPAID')paymentAmount=0;if(paymentStatus==='PARTIAL'&&(paymentAmount<=0||paymentAmount>=amount))return res.status(400).json({error:'Partial payment must be greater than ₹0 and less than the order total.'});if('payment_method' in req.body)req.body.payment_method=String(req.body.payment_method||'').trim().slice(0,80);if('customer_note' in req.body)req.body.customer_note=String(req.body.customer_note||'').slice(0,1000);const nextStatus=req.body.status||before.status;try{assertOrderTransition(before.status,nextStatus)}catch(e){return res.status(400).json({error:e.message})}const fields=['status','payment_status','payment_amount','payment_method','customer_note'];const allowed=fields.filter(k=>k in req.body||k==='payment_status'||k==='payment_amount');const tx=db.transaction(async ()=>{await db.prepare(`UPDATE orders SET ${allowed.map(k=>k+'=?').join(',')},updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(...allowed.map(k=>k==='payment_status'?paymentStatus:k==='payment_amount'?paymentAmount:req.body[k]),req.params.id);const o=await db.prepare('SELECT * FROM orders WHERE id=?').get(req.params.id);if(nextStatus==='CANCELLED'&&before.status!=='CANCELLED')await reverseInventoryForCancelledOrder(o,req.user.id);if(before.status==='CANCELLED'&&nextStatus!=='CANCELLED')await consumeInventoryForOrder(o,req.user.id);if(o.customer_id&&before.status!==o.status)notify(o.customer_id,'Order status updated',`Order ${o.order_number} is now ${o.status}.`,'ORDER_STATUS');if(o.customer_id&&before.payment_status!==o.payment_status)notify(o.customer_id,'Payment status updated',`Payment status for ${o.order_number}: ${o.payment_status}. Paid ₹${Number(o.payment_amount||0).toLocaleString('en-IN')} of ₹${Number(o.amount).toLocaleString('en-IN')}.`,'PAYMENT');await db.prepare('UPDATE enquiries SET status=? WHERE id=?').run(o.status,o.enquiry_id);await db.prepare('INSERT INTO enquiry_history(enquiry_id,event_type,event_label,note) VALUES(?,?,?,?)').run(o.enquiry_id,'ORDER',`Order ${o.status}`,`Order ${o.order_number}`);return o});try{res.json({ok:true,order:await tx()})}catch(e){res.status(400).json({error:e.message||'Could not update order'})}});
app.post('/api/admin/services',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const x=req.body;const name=String(x.name||'').trim();if(!name)return res.status(400).json({error:'Name required'});let price=null;try{if(x.starting_price!==undefined&&x.starting_price!==null&&x.starting_price!=='')price=normalizeMoney(x.starting_price,'Starting price')}catch(e){return res.status(400).json({error:e.message})}const order=Number(x.display_order??0);if(!Number.isInteger(order)||order<0)return res.status(400).json({error:'Display order must be a non-negative integer.'});const q=await db.prepare('INSERT INTO services(name,description,starting_price,badge,featured,visible,display_order) VALUES(?,?,?,?,?,?,?)').run(name,String(x.description||'').slice(0,2000),price,String(x.badge||'').slice(0,100),serviceFlag(x.featured),x.visible===false||x.visible===0||x.visible==='0'?0:1,order);res.status(201).json({id:q.lastInsertRowid})});
app.patch('/api/admin/services/:id',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{if(!await db.prepare('SELECT id FROM services WHERE id=?').get(req.params.id))return res.status(404).json({error:'Service not found'});const body={...req.body};if('name' in body){body.name=String(body.name||'').trim();if(!body.name)return res.status(400).json({error:'Service name cannot be empty.'})}if('starting_price' in body){try{body.starting_price=body.starting_price===null||body.starting_price===''?null:normalizeMoney(body.starting_price,'Starting price')}catch(e){return res.status(400).json({error:e.message})}}if('display_order' in body){body.display_order=Number(body.display_order);if(!Number.isInteger(body.display_order)||body.display_order<0)return res.status(400).json({error:'Display order must be a non-negative integer.'})}for(const k of ['featured','visible'])if(k in body)body[k]=serviceFlag(body[k]);if('description' in body)body.description=String(body.description||'').slice(0,2000);if('badge' in body)body.badge=String(body.badge||'').slice(0,100);const keys=['name','description','starting_price','badge','featured','visible','display_order'].filter(k=>k in body);if(!keys.length)return res.status(400).json({error:'Nothing to update'});await db.prepare(`UPDATE services SET ${keys.map(k=>k+'=?').join(',')} WHERE id=?`).run(...keys.map(k=>body[k]),req.params.id);res.json({ok:true})});
