app.get('/api/admin/customers',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const term=String(req.query.q||'').trim();let rows;if(term){const like='%'+term+'%';rows=await db.prepare(`SELECT u.id,u.name,u.email,u.active,u.created_at,COUNT(DISTINCT e.id) enquiries,COUNT(DISTINCT o.id) orders,COALESCE(SUM(CASE WHEN o.status!='CANCELLED' THEN o.amount ELSE 0 END),0) total_order_value,COALESCE(SUM(CASE WHEN o.status!='CANCELLED' THEN COALESCE(o.payment_amount,0) ELSE 0 END),0) paid_amount FROM users u LEFT JOIN enquiries e ON e.customer_id=u.id LEFT JOIN orders o ON o.customer_id=u.id WHERE u.role='CUSTOMER' AND (u.name LIKE ? OR u.email LIKE ?) GROUP BY u.id ORDER BY u.id DESC`).all(like,like)}else{rows=await db.prepare(`SELECT u.id,u.name,u.email,u.active,u.created_at,COUNT(DISTINCT e.id) enquiries,COUNT(DISTINCT o.id) orders,COALESCE(SUM(CASE WHEN o.status!='CANCELLED' THEN o.amount ELSE 0 END),0) total_order_value,COALESCE(SUM(CASE WHEN o.status!='CANCELLED' THEN COALESCE(o.payment_amount,0) ELSE 0 END),0) paid_amount FROM users u LEFT JOIN enquiries e ON e.customer_id=u.id LEFT JOIN orders o ON o.customer_id=u.id WHERE u.role='CUSTOMER' GROUP BY u.id ORDER BY u.id DESC`).all()}res.json(rows.map(x=>({...x,pending_amount:Math.max(0,Number(x.total_order_value)-Number(x.paid_amount))})))});
