app.get('/api/admin/business-dashboard',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{
 const inventory=await db.prepare(`SELECT COUNT(*) total,SUM(CASE WHEN stock<=min_stock THEN 1 ELSE 0 END) low,SUM(stock*cost_per_unit) stockValue FROM inventory_items WHERE active=1`).get();
 const production=await db.prepare(`SELECT stage,COUNT(*) count FROM production_jobs GROUP BY stage ORDER BY count DESC`).all();
 const deliveries=await db.prepare(`SELECT status,COUNT(*) count FROM deliveries GROUP BY status`).all();
 const complaints=await db.prepare(`SELECT status,COUNT(*) count FROM support_tickets GROUP BY status`).all();
 const services=await db.prepare(`SELECT service,COUNT(*) count FROM orders WHERE status!='CANCELLED' GROUP BY service ORDER BY count DESC LIMIT 10`).all();
 const resolution=await db.prepare(`SELECT ROUND(AVG((julianday(updated_at)-julianday(created_at))*24),1) hours FROM support_tickets WHERE status='CLOSED'`).get();
 res.json({inventory,production,deliveries,complaints,services,avgTicketResolutionHours:resolution.hours||0});
});
app.get('/api/admin/inventory',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>res.json(await db.prepare('SELECT * FROM inventory_items ORDER BY id DESC').all()));
app.post('/api/admin/inventory',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const x=req.body;if(!String(x.name||'').trim())return res.status(400).json({error:'Item name required'});const stock=Number(x.stock||0),min=Number(x.min_stock||0),cost=Number(x.cost_per_unit||0);if(![stock,min,cost].every(Number.isFinite)||stock<0||min<0||cost<0)return res.status(400).json({error:'Stock, minimum stock and cost must be non-negative numbers.'});const q=await db.prepare('INSERT INTO inventory_items(name,category,unit,stock,min_stock,cost_per_unit) VALUES(?,?,?,?,?,?)').run(String(x.name).trim(),String(x.category||'GENERAL').toUpperCase(),String(x.unit||'pcs').slice(0,30),stock,min,cost);logActivity(req.user.id,'INVENTORY_CREATE','INVENTORY',q.lastInsertRowid,String(x.name),ip(req));res.status(201).json({id:q.lastInsertRowid})});
app.patch('/api/admin/inventory/:id',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const item=await db.prepare('SELECT * FROM inventory_items WHERE id=?').get(req.params.id);if(!item)return res.status(404).json({error:'Inventory item not found'});if('stock' in req.body)return res.status(400).json({error:'Stock can only be changed through an IN/OUT inventory movement.'});if('min_stock' in req.body){const v=Number(req.body.min_stock);if(!Number.isFinite(v)||v<0)return res.status(400).json({error:'Minimum stock must be non-negative.'});req.body.min_stock=v;}if('cost_per_unit' in req.body){const v=Number(req.body.cost_per_unit);if(!Number.isFinite(v)||v<0)return res.status(400).json({error:'Cost per unit must be non-negative.'});req.body.cost_per_unit=v;}const keys=['name','category','unit','min_stock','cost_per_unit','active'].filter(k=>k in req.body);if(!keys.length)return res.status(400).json({error:'Nothing to update'});await db.prepare(`UPDATE inventory_items SET ${keys.map(k=>k+'=?').join(',')},updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(...keys.map(k=>req.body[k]),req.params.id);res.json({ok:true})});
app.post('/api/admin/inventory/:id/movement',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const item=await db.prepare('SELECT * FROM inventory_items WHERE id=?').get(req.params.id);const type=String(req.body.type||'IN').toUpperCase(),qty=Number(req.body.quantity),orderId=req.body.order_id==null||req.body.order_id===''?null:Number(req.body.order_id);if(!item||!Number.isFinite(qty)||qty<=0||!['IN','OUT'].includes(type))return res.status(400).json({error:'Invalid inventory movement'});if(orderId!==null&&(!Number.isInteger(orderId)||!await db.prepare('SELECT id FROM orders WHERE id=?').get(orderId)))return res.status(400).json({error:'Order reference is invalid'});if(type==='OUT'&&item.stock<qty)return res.status(400).json({error:'Insufficient stock'});await db.prepare('UPDATE inventory_items SET stock=stock'+(type==='IN'?'+':'-')+'?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(qty,item.id);await db.prepare('INSERT INTO inventory_movements(item_id,type,quantity,note,order_id,created_by) VALUES(?,?,?,?,?,?)').run(item.id,type,qty,String(req.body.note||''),orderId,req.user.id);res.json({ok:true})});
app.get('/api/admin/inventory/:id/movements',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>res.json(await db.prepare('SELECT m.*,u.name created_by_name FROM inventory_movements m LEFT JOIN users u ON u.id=m.created_by WHERE item_id=? ORDER BY id DESC LIMIT 100').all(req.params.id)));
app.get('/api/admin/staff',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>res.json(await db.prepare("SELECT id,name,email,role FROM users WHERE active=1 AND role IN ('ADMIN','SUPER_ADMIN') ORDER BY name").all()));
app.get('/api/admin/staff-assignments',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>res.json(await db.prepare("SELECT sa.*,o.order_number,u.name staff_name,u.email staff_email FROM staff_assignments sa JOIN orders o ON o.id=sa.order_id JOIN users u ON u.id=sa.user_id ORDER BY sa.id DESC").all()));
app.post('/api/admin/staff-assignments',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const order=await db.prepare('SELECT id,status FROM orders WHERE id=?').get(Number(req.body.order_id));const staff=await db.prepare("SELECT id FROM users WHERE id=? AND active=1 AND role IN ('ADMIN','SUPER_ADMIN')").get(Number(req.body.user_id));const task=cleanText(req.body.task||'GENERAL',100);if(!order||['CANCELLED','COMPLETED'].includes(order.status)||!staff||!task)return res.status(400).json({error:'Assign only an active staff member to a non-cancelled, non-completed order.'});const existing=await db.prepare('SELECT id FROM staff_assignments WHERE order_id=? AND user_id=? AND task=?').get(order.id,staff.id,task);let id=existing?.id;if(!id)id=(await db.prepare('INSERT INTO staff_assignments(order_id,user_id,task) VALUES(?,?,?)').run(order.id,staff.id,task)).lastInsertRowid;await db.prepare('UPDATE production_jobs SET assigned_to=?,updated_at=CURRENT_TIMESTAMP WHERE order_id=?').run(staff.id,order.id);res.status(201).json({ok:true,id,existing:!!existing})});
app.delete('/api/admin/staff-assignments/:id',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const a=await db.prepare('SELECT * FROM staff_assignments WHERE id=?').get(req.params.id);if(!a)return res.status(404).json({error:'Assignment not found'});await db.prepare('DELETE FROM staff_assignments WHERE id=?').run(a.id);const latest=await db.prepare('SELECT user_id FROM staff_assignments WHERE order_id=? ORDER BY id DESC LIMIT 1').get(a.order_id);await db.prepare('UPDATE production_jobs SET assigned_to=?,updated_at=CURRENT_TIMESTAMP WHERE order_id=?').run(latest?.user_id||null,a.order_id);res.json({ok:true})});
app.get('/api/admin/production',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{await db.prepare(`INSERT OR IGNORE INTO production_jobs(order_id) SELECT id FROM orders WHERE status!='CANCELLED'`).run();res.json(await db.prepare(`SELECT p.*,o.order_number,o.service,o.customer_id,u.name customer_name,au.name assigned_name FROM production_jobs p JOIN orders o ON o.id=p.order_id LEFT JOIN users u ON u.id=o.customer_id LEFT JOIN users au ON au.id=p.assigned_to ORDER BY p.id DESC`).all())});
app.patch('/api/admin/production/:orderId',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const order=await db.prepare('SELECT * FROM orders WHERE id=?').get(req.params.orderId);if(!order)return res.status(404).json({error:'Order not found'});if(order.status==='CANCELLED')return res.status(400).json({error:'Cancelled orders cannot enter production.'});if(order.status==='COMPLETED')return res.status(400).json({error:'Completed orders cannot be moved back into production.'});const stage=String(req.body.stage||'PENDING').trim().toUpperCase();const assigned=req.body.assigned_to!==undefined&&req.body.assigned_to!==null&&req.body.assigned_to!==''?Number(req.body.assigned_to):null;if(!Object.keys(PRODUCTION_STAGE_STATUS).includes(stage))return res.status(400).json({error:'Invalid production stage'});if(assigned!==null&&(!Number.isInteger(assigned)||!await db.prepare("SELECT id FROM users WHERE id=? AND role IN ('ADMIN','SUPER_ADMIN') AND active=1").get(assigned)))return res.status(400).json({error:'Staff member not found'});const syncedStatus=PRODUCTION_STAGE_STATUS[stage];try{assertOrderTransition(order.status,syncedStatus)}catch(e){return res.status(400).json({error:e.message})}const tx=db.transaction(async ()=>{await db.prepare(`INSERT INTO production_jobs(order_id,stage,assigned_to,expected_date,notes) VALUES(?,?,?,?,?) ON CONFLICT(order_id) DO UPDATE SET stage=excluded.stage,assigned_to=excluded.assigned_to,expected_date=excluded.expected_date,notes=excluded.notes,updated_at=CURRENT_TIMESTAMP`).run(order.id,stage,assigned,validDate(req.body.expected_date)?(req.body.expected_date||null):null,cleanText(req.body.notes,1000));await db.prepare('UPDATE orders SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(syncedStatus,order.id);await db.prepare('UPDATE enquiries SET status=? WHERE id=?').run(syncedStatus,order.enquiry_id);await db.prepare('INSERT INTO enquiry_history(enquiry_id,event_type,event_label,note) VALUES(?,?,?,?)').run(order.enquiry_id,'PRODUCTION',`Production ${stage}`,`Order ${order.order_number}`);if(order.customer_id&&order.status!==syncedStatus)notify(order.customer_id,'Production update',`Order ${order.order_number} is now ${syncedStatus}; production stage: ${stage}.`,'ORDER');return await db.prepare('SELECT * FROM orders WHERE id=?').get(order.id)});try{res.json({ok:true,order:await tx(),stage})}catch(e){res.status(400).json({error:e.message||'Could not update production'})}});
app.get('/api/admin/deliveries',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>res.json(await db.prepare(`SELECT d.*,o.order_number,o.service,u.name customer_name FROM deliveries d JOIN orders o ON o.id=d.order_id LEFT JOIN users u ON u.id=o.customer_id ORDER BY d.scheduled_date ASC,d.id DESC`).all()));
app.post('/api/admin/deliveries',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const x=req.body,o=await db.prepare('SELECT * FROM orders WHERE id=?').get(Number(x.order_id));if(!o)return res.status(404).json({error:'Order not found'});if(o.status==='CANCELLED')return res.status(400).json({error:'Cancelled orders cannot have an active delivery schedule.'});try{const dtype=String(x.type||'DELIVERY').trim().toUpperCase(),dstatus=String(x.status||'SCHEDULED').trim().toUpperCase(),date=x.scheduled_date?String(x.scheduled_date).trim():'',time=x.scheduled_time?String(x.scheduled_time).trim():'',phone=x.contact_phone?String(x.contact_phone).trim():'';if(!['DELIVERY','INSTALLATION','DELIVERY + INSTALLATION'].includes(dtype))throw Error('Invalid schedule type');if(!['SCHEDULED','IN TRANSIT','COMPLETED','CANCELLED'].includes(dstatus))throw Error('Invalid delivery status');if(!validDate(date)||!validTime(time))throw Error('Invalid scheduled date or time');if(phone&&!validPhone(phone))throw Error('Enter a valid Indian contact phone number');if(dstatus!=='CANCELLED'&&dstatus!=='COMPLETED'&&!date)throw Error('Scheduled date is required');const q=await db.prepare(`INSERT INTO deliveries(order_id,type,scheduled_date,scheduled_time,address,contact_phone,status,notes) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(order_id) DO UPDATE SET type=excluded.type,scheduled_date=excluded.scheduled_date,scheduled_time=excluded.scheduled_time,address=excluded.address,contact_phone=excluded.contact_phone,status=excluded.status,notes=excluded.notes,updated_at=CURRENT_TIMESTAMP`).run(o.id,dtype,date||null,time||null,cleanText(x.address,500),phone,dstatus,cleanText(x.notes,1000));if(dstatus==='COMPLETED'&&o.status!=='COMPLETED'){assertOrderTransition(o.status,'COMPLETED');await db.prepare("UPDATE orders SET status='COMPLETED',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(o.id);await db.prepare("UPDATE enquiries SET status='COMPLETED' WHERE id=?").run(o.enquiry_id)}if(o.customer_id)notify(o.customer_id,dstatus==='COMPLETED'?'Delivery completed':'Delivery scheduled',`Order ${o.order_number}: ${dtype.toLowerCase()} status is ${dstatus}.`,'DELIVERY');res.json({ok:true,id:q.lastInsertRowid})}catch(e){res.status(400).json({error:e.message||'Could not save delivery'})}});
app.patch('/api/admin/deliveries/:id',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const d=await db.prepare('SELECT * FROM deliveries WHERE id=?').get(req.params.id);if(!d)return res.status(404).json({error:'Delivery not found'});const o=await db.prepare('SELECT * FROM orders WHERE id=?').get(d.order_id);if(!o)return res.status(404).json({error:'Order not found'});try{const m={...d,...req.body},dtype=String(m.type||'DELIVERY').trim().toUpperCase(),dstatus=String(m.status||'SCHEDULED').trim().toUpperCase(),date=m.scheduled_date?String(m.scheduled_date).trim():'',time=m.scheduled_time?String(m.scheduled_time).trim():'',phone=m.contact_phone?String(m.contact_phone).trim():'';if(!['DELIVERY','INSTALLATION','DELIVERY + INSTALLATION'].includes(dtype)||!['SCHEDULED','IN TRANSIT','COMPLETED','CANCELLED'].includes(dstatus))throw Error('Invalid delivery details');if(!validDate(date)||!validTime(time))throw Error('Invalid scheduled date or time');if(phone&&!validPhone(phone))throw Error('Enter a valid Indian contact phone number');if(o.status==='CANCELLED'&&dstatus!=='CANCELLED')throw Error('Cancelled orders cannot have an active delivery schedule.');await db.prepare(`UPDATE deliveries SET type=?,scheduled_date=?,scheduled_time=?,address=?,contact_phone=?,status=?,notes=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(dtype,date||null,time||null,cleanText(m.address,500),phone,dstatus,cleanText(m.notes,1000),d.id);if(dstatus==='COMPLETED'&&o.status!=='COMPLETED'){assertOrderTransition(o.status,'COMPLETED');await db.prepare("UPDATE orders SET status='COMPLETED',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(o.id);await db.prepare("UPDATE enquiries SET status='COMPLETED' WHERE id=?").run(o.enquiry_id)}res.json({ok:true,delivery:await db.prepare('SELECT * FROM deliveries WHERE id=?').get(d.id)})}catch(e){res.status(400).json({error:e.message||'Could not update delivery'})}});
app.patch('/api/admin/orders/:id/refund',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const o=await db.prepare('SELECT * FROM orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});const status=String(req.body.refund_status||'NOT_REQUESTED').toUpperCase(),amount=Number(req.body.refund_amount||0);if(!['NOT_REQUESTED','REQUESTED','PROCESSING','REFUNDED','REJECTED'].includes(status)||!Number.isFinite(amount)||amount<0||amount>Number(o.payment_amount||0))return res.status(400).json({error:'Invalid refund details'});await db.prepare('UPDATE orders SET refund_status=?,refund_amount=?,refund_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(status,amount,cleanText(req.body.refund_note,500),o.id);res.json({ok:true})});
app.get('/api/admin/suppliers',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>res.json(await db.prepare('SELECT * FROM suppliers ORDER BY id DESC').all()));
app.post('/api/admin/suppliers',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const name=cleanText(req.body.name,120);if(!name)return res.status(400).json({error:'Supplier name required'});const q=await db.prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)').run(name,cleanText(req.body.phone,40),cleanText(req.body.email,160),cleanText(req.body.address,500));res.status(201).json({id:q.lastInsertRowid})});
app.post('/api/admin/inventory/purchases',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const itemId=Number(req.body.item_id),qty=Number(req.body.quantity),cost=Number(req.body.cost_per_unit),date=String(req.body.purchase_date||new Date().toISOString().slice(0,10));const item=await db.prepare('SELECT * FROM inventory_items WHERE id=? AND active=1').get(itemId);if(!item||!Number.isFinite(qty)||qty<=0||!Number.isFinite(cost)||cost<0||!validDate(date))return res.status(400).json({error:'Invalid purchase details'});const supplierId=req.body.supplier_id==null||req.body.supplier_id===''?null:Number(req.body.supplier_id);if(supplierId!==null&&!await db.prepare('SELECT id FROM suppliers WHERE id=? AND active=1').get(supplierId))return res.status(400).json({error:'Supplier not found'});const tx=db.transaction(async ()=>{const q=await db.prepare('INSERT INTO inventory_purchases(supplier_id,item_id,quantity,cost_per_unit,total_cost,purchase_date,note,created_by) VALUES(?,?,?,?,?,?,?,?)').run(supplierId,item.id,qty,cost,qty*cost,date,cleanText(req.body.note,500),req.user.id);await db.prepare('UPDATE inventory_items SET stock=stock+?,cost_per_unit=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(qty,cost,item.id);await db.prepare('INSERT INTO inventory_movements(item_id,type,quantity,note,created_by) VALUES(?,?,?,?,?)').run(item.id,'IN',qty,`Purchase #${q.lastInsertRowid}`,req.user.id);return q.lastInsertRowid});res.status(201).json({ok:true,id:await tx()})});
app.get('/api/admin/staff-profiles',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>res.json(await db.prepare("SELECT u.id,u.name,u.email,u.role,u.active,sp.phone,sp.designation,sp.joined_date,sp.notes FROM users u LEFT JOIN staff_profiles sp ON sp.user_id=u.id WHERE u.role IN ('ADMIN','SUPER_ADMIN') ORDER BY u.name").all()));
app.patch('/api/admin/staff-profiles/:id',auth,allow('SUPER_ADMIN'),async (req,res)=>{const u=await db.prepare("SELECT id FROM users WHERE id=? AND role IN ('ADMIN','SUPER_ADMIN')").get(req.params.id);if(!u)return res.status(404).json({error:'Staff member not found'});await db.prepare(`INSERT INTO staff_profiles(user_id,phone,designation,joined_date,notes) VALUES(?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET phone=excluded.phone,designation=excluded.designation,joined_date=excluded.joined_date,notes=excluded.notes,updated_at=CURRENT_TIMESTAMP`).run(u.id,cleanText(req.body.phone,40),cleanText(req.body.designation,100),req.body.joined_date||null,cleanText(req.body.notes,500));res.json({ok:true})});
app.post('/api/admin/staff-attendance',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const userId=Number(req.body.user_id),date=String(req.body.attendance_date||new Date().toISOString().slice(0,10)),status=String(req.body.status||'PRESENT').toUpperCase();if(!await db.prepare("SELECT id FROM users WHERE id=? AND role IN ('ADMIN','SUPER_ADMIN')").get(userId)||!validDate(date)||!['PRESENT','ABSENT','HALF_DAY','LEAVE'].includes(status))return res.status(400).json({error:'Invalid attendance'});await db.prepare(`INSERT INTO staff_attendance(user_id,attendance_date,status,note,created_by) VALUES(?,?,?,?,?) ON CONFLICT(user_id,attendance_date) DO UPDATE SET status=excluded.status,note=excluded.note,created_by=excluded.created_by`).run(userId,date,status,cleanText(req.body.note,300),req.user.id);res.json({ok:true})});
app.get('/api/admin/reports/orders.csv',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const rows=await db.prepare(`SELECT o.order_number,o.service,o.quantity,o.amount,o.status,o.payment_status,o.payment_amount,o.payment_method,o.created_at,u.name customer_name,u.email customer_email FROM orders o LEFT JOIN users u ON u.id=o.customer_id ORDER BY o.id DESC`).all();const escv=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv=[Object.keys(rows[0]||{order_number:1}).join(','),...rows.map(r=>Object.values(r).map(escv).join(','))].join('\n');res.setHeader('Content-Type','text/csv');res.setHeader('Content-Disposition','attachment; filename="rudra-arts-orders-report.csv"');res.send(csv)});
app.get('/api/admin/reports/inventory.csv',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const rows=await db.prepare('SELECT name,category,unit,stock,min_stock,cost_per_unit,created_at FROM inventory_items ORDER BY id DESC').all();const escv=v=>'"'+String(v??'').replace(/"/g,'""')+'"';res.setHeader('Content-Type','text/csv');res.setHeader('Content-Disposition','attachment; filename="rudra-arts-inventory-report.csv"');res.send([Object.keys(rows[0]||{name:1}).join(','),...rows.map(r=>Object.values(r).map(escv).join(','))].join('\n'))});
app.get('/api/admin/reports/customers.csv',auth,allow('SUPER_ADMIN','ADMIN'),async (req,res)=>{const rows=await db.prepare(`SELECT u.name,u.email,u.active,u.created_at,COUNT(DISTINCT e.id) enquiries,COUNT(DISTINCT o.id) orders,COALESCE(SUM(CASE WHEN o.status!='CANCELLED' THEN o.amount ELSE 0 END),0) order_value,COALESCE(SUM(CASE WHEN o.status!='CANCELLED' THEN o.payment_amount ELSE 0 END),0) paid FROM users u LEFT JOIN enquiries e ON e.customer_id=u.id LEFT JOIN orders o ON o.customer_id=u.id WHERE u.role='CUSTOMER' GROUP BY u.id ORDER BY u.id DESC`).all();const escv=v=>'"'+String(v??'').replace(/"/g,'""')+'"';res.setHeader('Content-Type','text/csv');res.setHeader('Content-Disposition','attachment; filename="rudra-arts-customers-report.csv"');res.send([Object.keys(rows[0]||{name:1}).join(','),...rows.map(r=>Object.values(r).map(escv).join(','))].join('\n'))});

